import { readFileSync } from 'node:fs';
import { describe, it, expect } from 'vitest';
import { parse } from '../parser/index.js';
import { simulate } from '../simulate.js';
import { BSIM3v3 } from './bsim3v3.js';
import { chargeParams, createTerminalCharges, evaluateTerminalCharges } from './bsim3v3-charge.js';

// Issue #626: ngspice-47 reference values for the BSIM3v3.3.0 charge model on
// identical decks, generated by benchmarks/bsim3-charge-626/reference.ts
// (`ngspice -b`, numdgt=15): the b3ld.c intrinsic capacitances
// @m1[cgg|cgd|cgs|cbg|cbd|cbs|cdg|cdd|cds], the state charges @m1[qg|qb|qd]
// and @m1[capbd|capbs], plus the AC terminal capacitance matrices.
type Quantity = 'cgg' | 'cgd' | 'cgs' | 'cbg' | 'cbd' | 'cbs' | 'cdg' | 'cdd' | 'cds'
  | 'qg' | 'qb' | 'qd' | 'capbd' | 'capbs';
type Source = 'vg' | 'vd' | 'vb';
interface Bias { vgs: number; vds: number; vbs: number }
interface ReferenceCase {
  name: string;
  type: 1 | -1;
  charges: { deck: string; points: (Bias & Record<Quantity, number>)[] };
  ac: { deck: string; frequency: number; points: (Bias & { c: Record<Source, Record<Source, number>> })[] };
}
const reference = JSON.parse(readFileSync(
  new URL('../../../../benchmarks/bsim3-charge-626/ngspice-47-charge.json', import.meta.url), 'utf8',
)) as { engine: string; cases: ReferenceCase[] };
// benchmarks/bsim3-charge-626/transient-reference.ts: two adder_mos_circ NAND
// gates at TMAX = 10 ps, node voltages sampled between the PULSE corners and
// the supply charge q(vcc) = integral of i(vcc) over a window around each sample.
type TranSignal = 'v(9)' | 'v(10)' | 'q(vcc)';
const nandReference = JSON.parse(readFileSync(
  new URL('../../../../benchmarks/bsim3-charge-626/ngspice-47-nand-tran.json', import.meta.url), 'utf8',
)) as {
  engine: string; deck: string; window: number;
  peak: Record<TranSignal, number>; samples: ({ time: number } & Record<TranSignal, number>)[];
};

/** Linear interpolation of a waveform at `t` (t inside the grid). */
function interpolate(time: readonly number[], values: readonly number[], t: number): number {
  const j = time.findIndex(x => x >= t);
  if (j <= 0) return values[Math.max(j, 0)];
  return values[j - 1] + (values[j] - values[j - 1]) * (t - time[j - 1]) / (time[j] - time[j - 1]);
}

/** Trapezoidal integral of a waveform over [lo, hi], as transient-reference.ts integrates ngspice. */
function integrate(time: readonly number[], values: readonly number[], lo: number, hi: number): number {
  const points: [number, number][] = [[lo, interpolate(time, values, lo)]];
  for (let k = 0; k < time.length; k++) if (time[k] > lo && time[k] < hi) points.push([time[k], values[k]]);
  points.push([hi, interpolate(time, values, hi)]);
  let charge = 0;
  for (let k = 1; k < points.length; k++) charge += 0.5 * (points[k][1] + points[k - 1][1]) * (points[k][0] - points[k - 1][0]);
  return charge;
}

// Same 1% acceptance as the #589 DC parity. ngspice prints 15 digits, so
// cancellation leaves ~1e-28 noise on quantities that are exactly zero; values
// below the floor (F or C) are compared absolutely.
const RELATIVE = 0.01;
const FLOOR = 1e-21;

function relativeError(actual: number, expected: number): number {
  return Math.abs(actual - expected) / Math.max(Math.abs(expected), FLOOR);
}

function deviceOf(deck: string): BSIM3v3 {
  const device = parse(deck).compile().devices.find((d): d is BSIM3v3 => d instanceof BSIM3v3);
  if (!device) throw new Error('no BSIM3 device in deck');
  return device;
}

describe('BSIM3v3 charge model matches ngspice-47 b3ld.c (#626)', () => {
  it('uses the ngspice-47 reference', () => {
    expect(reference.engine).toBe('ngspice-47');
    expect(reference.cases.length).toBeGreaterThanOrEqual(31);
    expect(nandReference.engine).toBe('ngspice-47');
  });

  // The adder_mos_circ gate (#626): before the b3ld.c charge port the NAND
  // output edges were ~20% of the swing off ngspice at the same 10 ps steps.
  it('NAND transient (adder_mos_circ gate): node voltages and supply charge within 1% of ngspice-47', async () => {
    const result = (await simulate(nandReference.deck)).transient!;
    const time = result.time;
    const supply = result.current('VCC');
    const half = nandReference.window / 2;
    let worst = { error: 0, label: '' };
    for (const sample of nandReference.samples) {
      const actual: Record<TranSignal, number> = {
        'v(9)': interpolate(time, result.voltage('9'), sample.time),
        'v(10)': interpolate(time, result.voltage('10'), sample.time),
        'q(vcc)': integrate(time, supply, sample.time - half, sample.time + half),
      };
      for (const signal of Object.keys(actual) as TranSignal[]) {
        const error = Math.abs(actual[signal] - sample[signal]) / nandReference.peak[signal];
        if (!(error <= worst.error)) worst = { error, label: `${signal} at ${sample.time}: ${actual[signal]} vs ${sample[signal]}` };
      }
    }
    expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    // A full 10 ps-step transient: 1.3-4.8 s under coverage on CI runners, so
    // the 5 s vitest default timed out on loaded runners (#735).
  }, 30_000);

  for (const c of reference.cases) {
    it(`${c.name}: intrinsic capacitances, state charges and junction capacitances`, () => {
      const device = deviceOf(c.charges.deck);
      const params = chargeParams(device.model, device.size);
      const out = createTerminalCharges();
      let worst = { error: 0, label: '' };
      for (const p of c.charges.points) {
        const tc = evaluateTerminalCharges(device.model, device.size, params, p.vgs, p.vds, p.vbs, out);
        const ic = tc.intrinsic;
        // b3ask.c reports every one of these multiplied by M.
        const m = device.size.m;
        const actual: Record<Quantity, number> = {
          cgg: m * ic.cggb, cgd: m * ic.cgdb, cgs: m * ic.cgsb, cbg: m * ic.cbgb, cbd: m * ic.cbdb,
          cbs: m * ic.cbsb, cdg: m * ic.cdgb, cdd: m * ic.cddb, cds: m * ic.cdsb,
          qg: m * tc.qg, qb: m * tc.qb, qd: m * tc.qd, capbd: m * tc.capbd, capbs: m * tc.capbs,
        };
        for (const q of Object.keys(actual) as Quantity[]) {
          const error = relativeError(actual[q], p[q]);
          if (!(error <= worst.error)) {
            worst = { error, label: `${q} at Vgs=${p.vgs} Vds=${p.vds} Vbs=${p.vbs}: ${actual[q]} vs ${p[q]}` };
          }
        }
      }
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });

    it(`${c.name}: AC terminal capacitance matrix`, async () => {
      const omega = 2 * Math.PI * c.ac.frequency;
      let worst = { error: 0, label: '' };
      for (const p of c.ac.points) {
        for (const excited of ['vg', 'vd', 'vb'] as const) {
          const deck = c.ac.deck
            .replace(/^VD d 0 DC 0 AC 0$/m, `VD d 0 DC ${c.type * p.vds} AC ${excited === 'vd' ? 1 : 0}`)
            .replace(/^VG g 0 DC 0 AC 0$/m, `VG g 0 DC ${c.type * p.vgs} AC ${excited === 'vg' ? 1 : 0}`)
            .replace(/^VB b 0 DC 0 AC 0$/m, `VB b 0 DC ${c.type * p.vbs} AC ${excited === 'vb' ? 1 : 0}`)
            .replace(/^\.end$/m, `.ac lin 1 ${c.ac.frequency} ${c.ac.frequency}\n.end`);
          const ac = (await simulate(deck)).ac!;
          for (const measured of ['vg', 'vd', 'vb'] as const) {
            const { magnitude, phase } = ac.current(measured.toUpperCase())[0];
            const capacitance = magnitude * Math.sin(phase * Math.PI / 180) / omega;
            const expected = p.c[excited][measured];
            const error = relativeError(capacitance, expected);
            if (!(error <= worst.error)) {
              worst = {
                error,
                label: `d i(${measured})/d ${excited} at Vgs=${p.vgs} Vds=${p.vds} Vbs=${p.vbs}: ${capacitance} vs ${expected}`,
              };
            }
          }
        }
      }
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });
  }
});
